import os, subprocess, time, textwrap
import b200probe
print(b200probe.harness_time.__doc__)
import inspect; print(inspect.signature(b200probe.harness_time))
os.makedirs("/tmp/oproj", exist_ok=True)
src = r'''
#include <cuda_runtime.h>
#include "cutlass/cutlass.h"
#include "cute/tensor.hpp"
#include "cutlass/gemm/device/gemm_universal_adapter.h"
#include "cutlass/gemm/kernel/gemm_universal.hpp"
#include "cutlass/gemm/kernel/tile_scheduler.hpp"
#include "cutlass/gemm/collective/collective_builder.hpp"
#include "cutlass/epilogue/collective/collective_builder.hpp"
#include "cutlass/util/packed_stride.hpp"
using namespace cute;
using EA = cutlass::bfloat16_t;
using LA = cutlass::layout::RowMajor;
using LB = cutlass::layout::ColumnMajor;
using LC = cutlass::layout::RowMajor;
constexpr int Al = 8;
using Tile = Shape<Int<TM>, Int<TN>, Int<TK>>;
using Clu = Shape<Int<CM>, _1, _1>;
using Epi = typename cutlass::epilogue::collective::CollectiveBuilder<
  cutlass::arch::Sm100, cutlass::arch::OpClassTensorOp, Tile, Clu,
  cutlass::epilogue::collective::EpilogueTileAuto, float, float,
  EA, LC, Al, EA, LC, Al, cutlass::epilogue::TmaWarpSpecialized2Sm>::CollectiveOp;
using Main = typename cutlass::gemm::collective::CollectiveBuilder<
  cutlass::arch::Sm100, cutlass::arch::OpClassTensorOp, EA, LA, Al, EA, LB, Al, float, Tile, Clu,
  cutlass::gemm::collective::StageCountAutoCarveout<static_cast<int>(sizeof(typename Epi::SharedStorage))>,
  cutlass::gemm::KernelTmaWarpSpecialized2SmSm100>::CollectiveOp;
#if SK
using Sched = cutlass::gemm::StreamKScheduler;
#else
using Sched = void;
#endif
using Kern = cutlass::gemm::kernel::GemmUniversal<Shape<int,int,int,int>, Main, Epi, Sched>;
using Gemm = cutlass::gemm::device::GemmUniversalAdapter<Kern>;
extern "C" size_t ws_size(int M, int N, int K) {
  typename Gemm::Arguments a{cutlass::gemm::GemmUniversalMode::kGemm, {M,N,K,1}, {}, {}};
  cutlass::KernelHardwareInfo hw; hw.device_id = 0; hw.sm_count = 148; a.hw_info = hw;
  return Gemm::get_workspace_size(a);
}
extern "C" int launch(const void* A, const void* R, const void* W, void* D, int M, int N, int K,
                      void* ws, int raster, int swz, int mode, cudaStream_t s) {
  auto sA = cutlass::make_cute_packed_stride(typename Kern::StrideA{}, make_shape(M, K, 1));
  auto sB = cutlass::make_cute_packed_stride(typename Kern::StrideB{}, make_shape(N, K, 1));
  auto sC = cutlass::make_cute_packed_stride(typename Kern::StrideC{}, make_shape(M, N, 1));
  auto sD = cutlass::make_cute_packed_stride(typename Kern::StrideD{}, make_shape(M, N, 1));
  cutlass::KernelHardwareInfo hw; hw.device_id = 0; hw.sm_count = 148;
  typename Gemm::Arguments a{cutlass::gemm::GemmUniversalMode::kGemm, {M,N,K,1},
    {(const EA*)A, sA, (const EA*)W, sB}, {{}, (const EA*)R, sC, (EA*)D, sD}, hw};
  a.epilogue.thread.alpha = 1.f; a.epilogue.thread.beta = 1.f;
  a.scheduler.raster_order = static_cast<decltype(a.scheduler.raster_order)>(raster);
  a.scheduler.max_swizzle_size = swz;
#if SK
  a.scheduler.decomposition_mode = static_cast<decltype(a.scheduler.decomposition_mode)>(mode);
#endif
  Gemm g;
  if (g.can_implement(a) != cutlass::Status::kSuccess) return 1;
  if (g.initialize(a, ws, s) != cutlass::Status::kSuccess) return 2;
  if (g.run(s) != cutlass::Status::kSuccess) return 3;
  return 0;
}
'''
open("/tmp/oproj/g.cu","w").write(src)
vars_ = {"b256x256c2":(256,256,64,2,0),"b256x128c2":(256,128,64,2,0),"b256x160c2":(256,160,64,2,0),"b256x256c2sk":(256,256,64,2,1)}
procs={}
t0=time.time()
for n,(tm,tn,tk,cm,sk) in vars_.items():
    cmd=f"nvcc -O3 -std=c++17 -gencode arch=compute_100a,code=sm_100a --expt-relaxed-constexpr -DNDEBUG -Xcompiler -fPIC -shared -I/usr/local/cutlass/include -I/usr/local/cutlass/tools/util/include -DTM={tm} -DTN={tn} -DTK={tk} -DCM={cm} -DSK={sk} /tmp/oproj/g.cu -o /tmp/oproj/{n}.so"
    procs[n]=subprocess.Popen(cmd,shell=True,stdout=subprocess.PIPE,stderr=subprocess.STDOUT,text=True)
for n,p in procs.items():
    try:
        out,_=p.communicate(timeout=max(1,105-(time.time()-t0)))
    except subprocess.TimeoutExpired:
        p.kill(); out="TIMEOUT"
    print(n, p.returncode, round(time.time()-t0,1), out[-1500:] if p.returncode else "")
print(os.listdir("/tmp/oproj"))

